/// The next version's slot built from scans (as for build) of the database as of
/// that version; invalid if the kernel cannot build it.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_stage_build(h: *const QHead, parts__n: usize, parts__p_partkey: *const i64, parts__p_type: *const u8, parts__p_type__off: *const usize, suppliers__n: usize, suppliers: *const SupplierInput, customers__n: usize, customers: *const CustomerInput, window_orders__n: usize, window_orders: *const OrderInput, lines__n: usize, lines: *const LineInput, nations__n: usize, nations__n_nationkey: *const i64, nations__n_name: *const u8, nations__n_name__off: *const usize, nations__n_regionkey: *const i64, regions__n: usize, regions__r_regionkey: *const i64, regions__r_name: *const u8, regions__r_name__off: *const usize) -> *mut QStaged {
    let parts__v: Vec<PartInput> = (0..parts__n).map(|i| PartInput { p_partkey: *parts__p_partkey.add(i), p_type: text(parts__p_type, parts__p_type__off, i) }).collect();
    let nations__v: Vec<NationInput> = (0..nations__n).map(|i| NationInput { n_nationkey: *nations__n_nationkey.add(i), n_name: text(nations__n_name, nations__n_name__off, i), n_regionkey: *nations__n_regionkey.add(i) }).collect();
    let regions__v: Vec<RegionInput> = (0..regions__n).map(|i| RegionInput { r_regionkey: *regions__r_regionkey.add(i), r_name: text(regions__r_name, regions__r_name__off, i) }).collect();
    if rec_on() {
        rec_rows("build", "parts", &["p_partkey:int", "p_type:text"], &parts__v, |r: &PartInput, o: &mut String| {
            o.push_str(&(r.p_partkey).to_string()); o.push(',');
            rec_text(&r.p_type, o);
        });
        rec_rows("build", "suppliers", &["s_suppkey:int", "s_nationkey:int"], slice(suppliers, suppliers__n), |r: &SupplierInput, o: &mut String| {
            o.push_str(&(r.s_suppkey).to_string()); o.push(',');
            o.push_str(&(r.s_nationkey).to_string());
        });
        rec_rows("build", "customers", &["c_custkey:int", "c_nationkey:int"], slice(customers, customers__n), |r: &CustomerInput, o: &mut String| {
            o.push_str(&(r.c_custkey).to_string()); o.push(',');
            o.push_str(&(r.c_nationkey).to_string());
        });
        rec_rows("build", "window_orders", &["o_orderkey:int", "o_custkey:int", "o_orderdate:date"], slice(window_orders, window_orders__n), |r: &OrderInput, o: &mut String| {
            o.push_str(&(r.o_orderkey).to_string()); o.push(',');
            o.push_str(&(r.o_custkey).to_string()); o.push(',');
            o.push_str(&(r.o_orderdate).to_string());
        });
        rec_rows("build", "lines", &["l_orderkey:int", "l_partkey:int", "l_suppkey:int", "l_extendedprice:dec2", "l_discount:dec2"], slice(lines, lines__n), |r: &LineInput, o: &mut String| {
            o.push_str(&(r.l_orderkey).to_string()); o.push(',');
            o.push_str(&(r.l_partkey).to_string()); o.push(',');
            o.push_str(&(r.l_suppkey).to_string()); o.push(',');
            o.push_str(&(r.l_extendedprice).to_string()); o.push(',');
            o.push_str(&(r.l_discount).to_string());
        });
        rec_rows("build", "nations", &["n_nationkey:int", "n_name:text", "n_regionkey:int"], &nations__v, |r: &NationInput, o: &mut String| {
            o.push_str(&(r.n_nationkey).to_string()); o.push(',');
            rec_text(&r.n_name, o); o.push(',');
            o.push_str(&(r.n_regionkey).to_string());
        });
        rec_rows("build", "regions", &["r_regionkey:int", "r_name:text"], &regions__v, |r: &RegionInput, o: &mut String| {
            o.push_str(&(r.r_regionkey).to_string()); o.push(',');
            rec_text(&r.r_name, o);
        });
        return ptr::null_mut();
    }
    Box::into_raw(Box::new(stage_build(&*h, parts__v, slice(suppliers, suppliers__n), slice(customers, customers__n), slice(window_orders, window_orders__n), slice(lines, lines__n), nations__v, regions__v)))
}

