/// Free a staged slot.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_staged_free(x: *mut QStaged) {
    if !x.is_null() {
        drop(Box::from_raw(x));
    }
}

/// Mark a commit in flight, visible from engine epoch `from`: 1, or 0 if one
/// is already in flight.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_begin(st: *const QStore, from: u64) -> i32 {
    (*st).begin(from) as i32
}

/// The commit in flight ended without a new version.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_abort(st: *const QStore) {
    (*st).abort()
}

/// Append the staged slot (consumed), current from engine epoch `from`; keep the
/// versions snapshots at or after `floor` select; end_commit != 0 also ends the
/// commit in flight.  0: appended; 1: stale (the store now holds one invalid version,
/// or, for a build during a commit, is unchanged).  HOST CONTRACT: staged on this store.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_install(st: *const QStore, p: *mut QStaged, from: u64, floor: u64, end_commit: i32) -> i32 {
    let p = (*Box::from_raw(p)).into_prepared(&*st);
    let r = if end_commit != 0 { (*st).commit(p, from, floor) } else { (*st).install(p, from, floor) };
    match r {
        Install::Applied => 0,
        Install::Stale => 1,
    }
}

/// The reading of a snapshot at engine epoch `at` (0: the newest), waiting up
/// to `tries` checks for a pending commit.  *status: 0 a reading (returned;
/// free it), 1 invalid, 2 still pending, 3 not visible.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_read(st: *const QStore, at: u64, tries: u64, status: *mut i32) -> *mut QReading {
    let (code, r) = match (*st).read(at, tries) {
        Read::Found(r) if r.state().is_some() => (0, Box::into_raw(Box::new(r))),
        Read::Found(_) => (1, ptr::null_mut()),
        Read::Pending => (2, ptr::null_mut()),
        Read::NotVisible => (3, ptr::null_mut()),
    };
    if !status.is_null() {
        *status = code;
    }
    r
}

/// Free a reading.
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_reading_free(x: *mut QReading) {
    if !x.is_null() {
        drop(Box::from_raw(x));
    }
}

/// The query's answer on the reading (THEOREM 5.4, gen_world.rs), or NULL (the host then
/// answers with SQL).
#[no_mangle]
pub unsafe extern "C" fn tpchq8vgens_answer(r: *const QReading, p1: *const u8, p1__len: usize, p2: *const u8, p2__len: usize, p3: *const u8, p3__len: usize) -> *mut FfiResult {
    match answer(&*r, slice(p1, p1__len), slice(p2, p2__len), slice(p3, p3__len)) {
        Some(rows) => Box::into_raw(Box::new(FfiResult { rows })),
        None => ptr::null_mut(),
    }
}

